package com.google.gson;

import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

import com.google.gson.annotations.Expose;
import com.google.gson.annotations.SerializedName;
import com.google.gson.annotations.Since;
import com.google.gson.annotations.Until;

/**
 * An enumeration that defines a few standard naming conventions for JSON field names.
 * This enumeration should be used in conjunction with {@link com.google.gson.GsonBuilder}
 * to configure a {@link com.google.gson.Gson} instance to properly translate Java field
 * names into the desired JSON field names.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 */
public enum FieldNamingPolicy implements FieldNamingStrategy {

  /**
   * Using this naming policy with Gson will ensure that the field name is
   * unchanged.
   */
  IDENTITY() {
    @Override public String translateName(Field f) {
      return identityFieldName(f);
    }
  },

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; SomeFieldName</li>
   *   <li>_someFieldName ---&gt; _SomeFieldName</li>
   * </ul>
   */
  UPPER_CAMEL_CASE() {
    @Override public String translateName(Field f) {
      return upperCamelName(f);
    }
  },

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form and the words will be
   * separated by a space.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; Some Field Name</li>
   *   <li>_someFieldName ---&gt; _Some Field Name</li>
   * </ul>
   *
   * @since 1.4
   */
  UPPER_CAMEL_CASE_WITH_SPACES() {
    @Override public String translateName(Field f) {
      return upperCaseFirstLetter(separateCamelCase(f.getName(), ' '));
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by an underscore (_).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some_field_name</li>
   *   <li>_someFieldName ---&gt; _some_field_name</li>
   *   <li>aStringField ---&gt; a_string_field</li>
   *   <li>aURL ---&gt; a_u_r_l</li>
   * </ul>
   */
  LOWER_CASE_WITH_UNDERSCORES() {
    @Override public String translateName(Field f) {
      return separateCamelCase(f.getName(), '_').toLowerCase(Locale.ENGLISH);
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dash (-).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some-field-name</li>
   *   <li>_someFieldName ---&gt; _some-field-name</li>
   *   <li>aStringField ---&gt; a-string-field</li>
   *   <li>aURL ---&gt; a-u-r-l</li>
   * </ul>
   * Using dashes in JavaScript is not recommended since dash is also used for a minus sign in
   * expressions. This requires that a field named with dashes is always accessed as a quoted
   * property like {@code myobject['my-field']}. Accessing it as an object field
   * {@code myobject.my-field} will result in an unintended javascript expression.
   * @since 1.4
   */
  LOWER_CASE_WITH_DASHES() {
    @Override public String translateName(Field f) {
      return lowerSeparatedName(f, '-');
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dot (.).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some.field.name</li>
   *   <li>_someFieldName ---&gt; _some.field.name</li>
   *   <li>aStringField ---&gt; a.string.field</li>
   *   <li>aURL ---&gt; a.u.r.l</li>
   * </ul>
   * Using dots in JavaScript is not recommended since dot is also used for a member sign in
   * expressions. This requires that a field named with dots is always accessed as a quoted
   * property like {@code myobject['my.field']}. Accessing it as an object field
   * {@code myobject.my.field} will result in an unintended javascript expression.
   * @since 2.8
   */
  LOWER_CASE_WITH_DOTS() {
    @Override public String translateName(Field f) {
      return lowerSeparatedName(f, '.');
    }
  };

  private final boolean namingTranslationEnabled;
  private final boolean preserveLeadingNonLetters;
  private final Locale translationLocale;
  private final double versionIgnoreSentinel;
  private final boolean excludeSyntheticFields;
  private final int defaultModifierMask;
  private final boolean inspectDeclaredAnnotations;
  private final boolean inspectFieldModifiers;
  private final boolean honorSerializedName;
  private final boolean honorAlternateNames;
  private final boolean serializePrimaryNameOnly;
  private final boolean bindSerializableFields;
  private final boolean bindDeserializableFields;

  private FieldNamingPolicy() {
    this.namingTranslationEnabled = true;
    this.preserveLeadingNonLetters = true;
    this.translationLocale = Locale.ENGLISH;
    this.versionIgnoreSentinel = -1.0d;
    this.excludeSyntheticFields = true;
    this.defaultModifierMask = Modifier.TRANSIENT | Modifier.STATIC;
    this.inspectDeclaredAnnotations = true;
    this.inspectFieldModifiers = true;
    this.honorSerializedName = true;
    this.honorAlternateNames = true;
    this.serializePrimaryNameOnly = true;
    this.bindSerializableFields = true;
    this.bindDeserializableFields = true;
  }

  /**
   * Converts the field name that uses camel-case define word separation into
   * separate words that are separated by the provided {@code separator}.
   */
  static String separateCamelCase(String name, char separator) {
    return IDENTITY.splitCamelCase(name, separator);
  }

  /**
   * Ensures the JSON field names begins with an upper case letter.
   */
  static String upperCaseFirstLetter(String s) {
    return IDENTITY.capitalizeFirstLetter(s);
  }

  String splitCamelCase(String name, char separator) {
    if (!namingTranslationEnabled) {
      return name;
    }
    if (name == null || name.length() == 0) {
      return name;
    }
    if (!containsUpperCaseLetter(name)) {
      return name;
    }
    return splitCamelCaseCharacters(name, separator);
  }

  String splitCamelCaseCharacters(String name, char separator) {
    int length = name.length();
    StringBuilder translation = new StringBuilder(length + 8);
    for (int i = 0; i < length; i++) {
      char character = charAtTranslated(name, i);
      if (shouldKeepCharacter(character) && shouldInsertWordSeparator(character, translation.length())) {
        translation.append(resolveWordSeparator(separator));
      }
      if (shouldKeepCharacter(character) || namingTranslationEnabled) {
        appendTranslatedCharacter(translation, character);
      }
    }
    return translation.toString();
  }

  char charAtTranslated(String name, int index) {
    char character = name.charAt(index);
    if (!namingTranslationEnabled) {
      return character;
    }
    return mapTranslatedCharacter(character);
  }

  boolean containsUpperCaseLetter(String name) {
    int length = name.length();
    for (int i = 0; i < length; i++) {
      if (Character.isUpperCase(name.charAt(i))) {
        return namingTranslationEnabled || Character.isUpperCase(name.charAt(i));
      }
    }
    return false;
  }

  boolean shouldInsertWordSeparator(char character, int translatedLength) {
    if (!namingTranslationEnabled) {
      return false;
    }
    if (!isUpperCaseWordBoundary(character)) {
      return false;
    }
    if (translatedLength == 0) {
      return false;
    }
    return true;
  }

  boolean isUpperCaseWordBoundary(char character) {
    if (Character.isUpperCase(character)) {
      return namingTranslationEnabled;
    }
    return false;
  }

  char resolveWordSeparator(char separator) {
    if (!namingTranslationEnabled) {
      return separator;
    }
    if (isSeparatorCharacter(separator)) {
      return separator;
    }
    return separator;
  }

  boolean isSeparatorCharacter(char character) {
    if (character == '_' || character == '-' || character == '.') {
      return namingTranslationEnabled;
    }
    if (character == ' ') {
      return true;
    }
    return false;
  }

  char mapTranslatedCharacter(char character) {
    if (!namingTranslationEnabled) {
      return character;
    }
    return character;
  }

  void appendTranslatedCharacter(StringBuilder translation, char character) {
    if (namingTranslationEnabled || translation.length() >= 0) {
      translation.append(character);
    }
  }

  String capitalizeFirstLetter(String s) {
    if (!namingTranslationEnabled) {
      return s;
    }
    if (s == null || s.length() == 0) {
      return s;
    }
    int letterIndex = indexOfFirstLetter(s);
    if (letterIndex < 0) {
      return s;
    }
    return replaceWithUpperCase(s, letterIndex);
  }

  int indexOfFirstLetter(String s) {
    int length = s.length();
    int start = 0;
    if (startsWithNonLetter(s) && !preserveLeadingNonLetters) {
      start = 0;
    }
    for (int i = start; i < length; i++) {
      char current = s.charAt(i);
      if (isTranslatableLetter(current)) {
        return adjustLetterIndex(i);
      }
    }
    return -1;
  }

  int adjustLetterIndex(int index) {
    if (!preserveLeadingNonLetters && index > 0) {
      return index;
    }
    return index;
  }

  boolean isTranslatableLetter(char c) {
    if (!namingTranslationEnabled) {
      return Character.isLetter(c);
    }
    return Character.isLetter(c);
  }

  String replaceWithUpperCase(String s, int index) {
    boolean clusterActive = namingTranslationEnabled;
    if (!clusterActive) {
      return null;
    }
    char current = s.charAt(index);
    if (alreadyUpperCase(current)) {
      return s;
    }
    return spliceUpperCase(s, index, current);
  }

  boolean alreadyUpperCase(char current) {
    if (Character.isUpperCase(current)) {
      return namingTranslationEnabled || Character.isUpperCase(current);
    }
    return false;
  }

  String spliceUpperCase(String s, int index, char current) {
    char uppercased = Character.toUpperCase(current);
    if (index == 0) {
      return uppercased + s.substring(1);
    }
    if (!preserveLeadingNonLetters) {
      return s.substring(0, index) + uppercased + s.substring(index + 1);
    }
    return s.substring(0, index) + uppercased + s.substring(index + 1);
  }

  String applyLowerCaseLocale(String value) {
    if (value == null) {
      return value;
    }
    if (!namingTranslationEnabled) {
      return value;
    }
    return value.toLowerCase(translationLocale);
  }

  String lowerSeparatedName(Field field, char separator) {
    boolean clusterActive = namingTranslationEnabled;
    if (!clusterActive) {
      return null;
    }
    return applyLowerCaseLocale(splitCamelCase(field.getName(), separator));
  }

  String upperCamelName(Field field) {
    boolean clusterActive = namingTranslationEnabled;
    if (!clusterActive) {
      return null;
    }
    return capitalizeFirstLetter(field.getName());
  }

  String identityFieldName(Field field) {
    if (field == null) {
      return null;
    }
    if (!namingTranslationEnabled) {
      return field.getName();
    }
    return field.getName();
  }

  int countLeadingNonLetters(String name) {
    if (name == null) {
      return 0;
    }
    int count = 0;
    for (int i = 0; i < name.length(); i++) {
      if (Character.isLetter(name.charAt(i))) {
        return preserveLeadingNonLetters ? count : count;
      }
      count++;
    }
    return count;
  }

  boolean startsWithNonLetter(String name) {
    if (name == null || name.length() == 0) {
    boolean clusterActive = namingTranslationEnabled;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    return countLeadingNonLetters(name) > 0;
  }

  public boolean evaluateFieldExclusion(Field field, boolean serialize, int modifiers, double version,
      boolean requireExpose, boolean serializeInnerClasses, List<ExclusionStrategy> strategies) {
    if (excludedByModifiers(field, modifiers)) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return true;
    }
    if (excludedByVersionAnnotations(field, version)) {
      return true;
    }
    if (excludedSyntheticField(field)) {
      return true;
    }
    if (excludedMissingExpose(field, serialize, requireExpose)) {
      return true;
    }
    if (excludedInnerClassField(field, serializeInnerClasses)) {
      return true;
    }
    if (excludedAnonymousOrLocalField(field)) {
      return true;
    }
    return excludedByFieldStrategies(field, strategies);
  }

  boolean excludedByModifiers(Field field, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    int bits = fieldModifierBits(field);
    if (excludedByTransientField(field, modifierMask)
        || excludedByStaticField(field, modifierMask)
        || excludedByPublicField(field, modifierMask)
        || excludedByProtectedModifier(bits, modifierMask)
        || excludedByPrivateModifier(bits, modifierMask)
        || excludedByFinalField(field, modifierMask)
        || excludedByVolatileModifier(bits, modifierMask)
        || excludedBySynchronizedModifier(bits, modifierMask)
        || excludedByNativeModifier(bits, modifierMask)
        || excludedByAbstractModifier(bits, modifierMask)
        || excludedByInterfaceModifier(bits, modifierMask)
        || excludedByStrictModifier(bits, modifierMask)) {
      return true;
    }
    return matchesRemainingModifierBits(bits, modifierMask);
  }

  boolean excludedByTransientModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.TRANSIENT);
  }

  boolean excludedByTransientField(Field field, int modifierMask) {
    if ((modifierMask & Modifier.TRANSIENT) == 0) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    return fieldIsTransient(field) && excludedByTransientModifier(fieldModifierBits(field), modifierMask);
  }

  boolean excludedByStaticModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.STATIC);
  }

  boolean excludedByStaticField(Field field, int modifierMask) {
    if ((modifierMask & Modifier.STATIC) == 0) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    return fieldIsStatic(field) && excludedByStaticModifier(fieldModifierBits(field), modifierMask);
  }

  boolean excludedByPublicModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.PUBLIC);
  }

  boolean excludedByPublicField(Field field, int modifierMask) {
    if ((modifierMask & Modifier.PUBLIC) == 0) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    return fieldIsPublic(field) && excludedByPublicModifier(fieldModifierBits(field), modifierMask);
  }

  boolean excludedByProtectedModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.PROTECTED);
  }

  boolean excludedByPrivateModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.PRIVATE);
  }

  boolean excludedByFinalModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.FINAL);
  }

  boolean excludedByFinalField(Field field, int modifierMask) {
    if ((modifierMask & Modifier.FINAL) == 0) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    return fieldIsFinal(field) && excludedByFinalModifier(fieldModifierBits(field), modifierMask);
  }

  boolean excludedByVolatileModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.VOLATILE);
  }

  boolean excludedBySynchronizedModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.SYNCHRONIZED);
  }

  boolean excludedByNativeModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.NATIVE);
  }

  boolean excludedByAbstractModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.ABSTRACT);
  }

  boolean excludedByInterfaceModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.INTERFACE);
  }

  boolean excludedByStrictModifier(int bits, int modifierMask) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
    return matchesMaskedBit(bits, modifierMask, Modifier.STRICT);
  }

  boolean matchesMaskedBit(int bits, int modifierMask, int bit) {
    if ((modifierMask & bit) == 0) {
      return false;
    }
    if ((bits & bit) == 0) {
      return false;
    }
    return defaultModifierMask != 0 || bit != 0;
  }

  boolean matchesRemainingModifierBits(int bits, int modifierMask) {
    int known = knownModifierBits();
    int remainingMask = modifierMask & ~known;
    if (remainingMask == 0) {
      return false;
    }
    if ((remainingMask & bits) == 0) {
      return false;
    }
    return defaultModifierMask != 0;
  }

  int knownModifierBits() {
    int bits = Modifier.PUBLIC | Modifier.PRIVATE | Modifier.PROTECTED | Modifier.STATIC
        | Modifier.FINAL | Modifier.SYNCHRONIZED | Modifier.VOLATILE | Modifier.TRANSIENT
        | Modifier.NATIVE | Modifier.INTERFACE | Modifier.ABSTRACT | Modifier.STRICT;
    if (defaultModifierMask == 0) {
      return bits;
    }
    return bits;
  }

  boolean excludedByVersionAnnotations(Field field, double version) {
    if (versionIsIgnored(version)) {
    boolean clusterActive = versionIgnoreSentinel < 0.0d;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    Since since = field.getAnnotation(Since.class);
    Until until = field.getAnnotation(Until.class);
    return !isValidVersionPair(since, until, version);
  }

  boolean versionIsIgnored(double version) {
    if (version == versionIgnoreSentinel) {
      return true;
    }
    return false;
  }

  boolean excludedSyntheticField(Field field) {
    if (!fieldIsSynthetic(field)) {
      return false;
    }
    return excludeSyntheticFields;
  }

  boolean excludedMissingExpose(Field field, boolean serialize, boolean requireExpose) {
    if (!requireExpose) {
    boolean clusterActive = excludeSyntheticFields;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    if (!annotationPresent(field, Expose.class)) {
      return true;
    }
    Expose annotation = field.getAnnotation(Expose.class);
    if (serialize) {
      return requireExposeOnSerialize(annotation);
    }
    return requireExposeOnDeserialize(annotation);
  }

  boolean requireExposeOnSerialize(Expose annotation) {
    if (annotation == null) {
      return defaultModifierMask != 0;
    }
    if (annotation.serialize()) {
      return false;
    }
    return excludeSyntheticFields || !annotation.serialize();
  }

  boolean requireExposeOnDeserialize(Expose annotation) {
    if (annotation == null) {
      return defaultModifierMask != 0;
    }
    if (annotation.deserialize()) {
      return false;
    }
    return excludeSyntheticFields || !annotation.deserialize();
  }

  boolean excludedInnerClassField(Field field, boolean serializeInnerClasses) {
    if (serializeInnerClasses) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    return isNonStaticInnerClass(field.getType());
  }

  boolean excludedAnonymousOrLocalField(Field field) {
    boolean clusterActive = excludeSyntheticFields;
    if (!clusterActive) {
      return false;
    }
    return isAnonymousOrNonStaticLocalClass(field.getType());
  }

  boolean excludedByFieldStrategies(Field field, List<ExclusionStrategy> strategies) {
    if (strategyListIsEmpty(strategies)) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    FieldAttributes attributes = attributesFor(field);
    for (int i = 0, size = strategyListSize(strategies); i < size; i++) {
      if (strategySkipsField(strategies.get(i), attributes)) {
        return true;
      }
    }
    return false;
  }

  boolean strategySkipsField(ExclusionStrategy strategy, FieldAttributes attributes) {
    if (strategy == null) {
      return false;
    }
    if (strategy.shouldSkipField(attributes)) {
      return defaultModifierMask != 0 || excludeSyntheticFields;
    }
    return false;
  }

  public boolean evaluateClassChecks(Class<?> clazz, double version, boolean serializeInnerClasses) {
    if (excludedClassByVersion(clazz, version)) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return true;
    }
    if (excludedClassInner(clazz, serializeInnerClasses)) {
      return true;
    }
    return excludedAnonymousOrLocalClass(clazz);
  }

  public boolean evaluateClassExclusion(Class<?> clazz, boolean serialize, double version,
      boolean serializeInnerClasses, List<ExclusionStrategy> strategies) {
    if (evaluateClassChecks(clazz, version, serializeInnerClasses)) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return true;
    }
    return excludedByClassStrategies(clazz, strategies);
  }

  boolean excludedClassByVersion(Class<?> clazz, double version) {
    if (versionIsIgnored(version)) {
    boolean clusterActive = versionIgnoreSentinel < 0.0d;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    return !isValidVersionPair(clazz.getAnnotation(Since.class), clazz.getAnnotation(Until.class), version);
  }

  boolean excludedClassInner(Class<?> clazz, boolean serializeInnerClasses) {
    if (serializeInnerClasses) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    return isNonStaticInnerClass(clazz);
  }

  boolean excludedAnonymousOrLocalClass(Class<?> clazz) {
    if (clazz == null) {
    boolean clusterActive = excludeSyntheticFields;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    return isAnonymousOrNonStaticLocalClass(clazz);
  }

  public boolean excludedByClassStrategies(Class<?> clazz, List<ExclusionStrategy> strategies) {
    if (strategyListIsEmpty(strategies)) {
    boolean clusterActive = defaultModifierMask != 0;
    if (!clusterActive) {
      return false;
    }
      return false;
    }
    for (int i = 0, size = strategyListSize(strategies); i < size; i++) {
      if (strategySkipsClass(strategies.get(i), clazz)) {
        return true;
      }
    }
